import ReactDOM from "react-dom/client";

// ─── API URLs ────────────────────────────────────────────────────────────────
const KPIS_API = "/api/x_2056099_indust_0/dashboard_api/kpis";
const OPERATOR_API = "/api/x_2056099_indust_0/operator_api/summary";
const ALERTS_API = "/api/x_2056099_indust_0/alert_center_api/alerts?limit=50";

// ─── Brand Colors ────────────────────────────────────────────────────────────
const BRAND = {
 navy: "#0f2438",
 navyLight: "#1a3a5c",
 accent: "#2563eb",
 white: "#ffffff",
 bgPage: "#f1f5f9",
 bgCard: "#ffffff",
 border: "#e2e8f0",
 borderLight: "#f0f0f0",
 textPrimary: "#0f172a",
 textSecondary: "#475569",
 textTertiary: "#94a3b8",
 severityCritical: "#dc2626",
 severityHigh: "#ea580c",
 severityMedium: "#ca8a04",
 severityLow: "#16a34a",
 info: "#0284c7",
};

// ─── Types ───────────────────────────────────────────────────────────────────
interface KpiData {
 totalStock: number;
 lowStock: number;
 openAlerts: number;
 pendingInspections: number;
 categories: { type: string; label: string; count: number; availableQty: number }[];
 alerts: { critical: number; high: number; open: number; expiredMaterial: number; qualityFailure: number; materialShortage: number };
 quality: { pending: number; passed: number; failed: number; blockedBatches: number };
 requests: { draft: number; pendingApproval: number; approved: number; inProgress: number; completed: number; rejected: number };
 recentTransactions: { number: string; material: string; quantity: string; transactionType: string; transactionDate: string; status: string }[];
}

interface OperatorData {
 activeOrders: number;
 inProgressOrders: number;
 plannedOrders: number;
 pendingRequests: number;
 activeAlerts: number;
 criticalAlerts: number;
 availableResources: number;
 maintenanceRequired: number;
}

interface AlertRecord {
 sys_id: string;
 number: string;
 alert_type: string;
 severity: string;
 alert_message: string;
 status: string;
 alert_date: string;
 inventory_stock: string;
 assigned_to: string;
}

interface AlertsData {
 summary: { critical: number; high: number; medium: number; low: number; open: number };
 alerts: AlertRecord[];
}

type SectionKey =
 | "dashboard"
 | "customer-orders"
 | "production"
 | "schedule"
 | "inventory"
 | "procurement"
 | "suppliers"
 | "alerts"
 | "forecasting"
 | "digital-twin";

interface NavItem {
 key: SectionKey;
 label: string;
 icon: string;
}

// ─── Navigation Items ────────────────────────────────────────────────────────
const NAV_ITEMS: NavItem[] = [
 { key: "dashboard", label: "Dashboard", icon: "■" },
 { key: "customer-orders", label: "Customer Orders", icon: "▶" },
 { key: "production", label: "Production & Machines", icon: "⚙" },
 { key: "schedule", label: "Schedule Planner", icon: "☰" },
 { key: "inventory", label: "Inventory", icon: "☷" },
 { key: "procurement", label: "Procurement", icon: "◆" },
 { key: "suppliers", label: "Suppliers", icon: "★" },
 { key: "alerts", label: "Alerts & Exceptions", icon: "⚠" },
 { key: "forecasting", label: "Demand Forecasting", icon: "▲" },
 { key: "digital-twin", label: "Digital Twin", icon: "◎" },
];

// ─── Helpers ─────────────────────────────────────────────────────────────────
function getToken(): string {
 return (window as any).g_ck || "";
}

async function apiFetch<T>(url: string): Promise<T | null> {
 try {
 const resp = await fetch(url, {
 headers: { Accept: "application/json", "X-UserToken": getToken() },
 });
 if (!resp.ok) return null;
 const json = await resp.json();
 return json?.result ?? null;
 } catch {
 return null;
 }
}

function severityColor(severity: string): string {
 const s = severity.toLowerCase();
 if (s === "critical") return BRAND.severityCritical;
 if (s === "high") return BRAND.severityHigh;
 if (s === "medium") return BRAND.severityMedium;
 if (s === "low") return BRAND.severityLow;
 return BRAND.textTertiary;
}

function formatAlertType(type: string): string {
 return type
 .replace(/_/g, " ")
 .replace(/\b\w/g, (c) => c.toUpperCase());
}

function formatDate(dateStr: string): string {
 if (!dateStr) return "—";
 try {
 const d = new Date(dateStr);
 return d.toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" });
 } catch {
 return dateStr;
 }
}

// ─── Spinner Component ──────────────────────────────────────────────────────
function Spinner() {
 const [rotation, setRotation] = useState(0);
 useEffect(() => {
 const id = setInterval(() => setRotation((r) => r + 6), 16);
 return () => clearInterval(id);
 }, []);
 return (
 <div
 style={{
 width: 28,
 height: 28,
 border: `3px solid ${BRAND.border}`,
 borderTopColor: BRAND.navy,
 borderRadius: "50%",
 transform: `rotate(${rotation}deg)`,
 }}
 />
 );
}

function LoadingState({ message }: { message?: string }) {
 return (
 <div style={{ display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", padding: 48, gap: 12 }}>
 <Spinner />
 <span style={{ fontSize: 13, color: BRAND.textTertiary }}>{message || "Loading…"}</span>
 </div>
 );
}

// ─── Card Shell ──────────────────────────────────────────────────────────────
function Card({
 children,
 style,
}: {
 children?: React.ReactNode;
 style?: CSSProperties;
}) {
 return (
 <div
 style={{
 background: BRAND.bgCard,
 borderRadius: 10,
 border: `1px solid ${BRAND.border}`,
 padding: 24,
 ...style,
 }}
 >
 {children}
 </div>
 );
}

function CardTitle({ children }: { children?: React.ReactNode }) {
 return (
 <h3
 style={{
 margin: "0 0 16px 0",
 fontSize: 15,
 fontWeight: 700,
 color: BRAND.textPrimary,
 letterSpacing: "0.01em",
 }}
 >
 {children}
 </h3>
 );
}

// ─── KPI Card ────────────────────────────────────────────────────────────────
function KpiCard({
 value,
 label,
 color,
 borderColor,
}: {
 value: number | string;
 label: string;
 color?: string;
 borderColor?: string;
}) {
 return (
 <div
 style={{
 background: BRAND.bgCard,
 borderRadius: 10,
 border: `1px solid ${BRAND.border}`,
 borderTop: borderColor ? `3px solid ${borderColor}` : `1px solid ${BRAND.border}`,
 padding: "20px 16px",
 display: "flex",
 flexDirection: "column",
 alignItems: "center",
 gap: 6,
 minWidth: 0,
 }}
 >
 <span
 style={{
 fontSize: 28,
 fontWeight: 700,
 color: color || BRAND.navy,
 lineHeight: 1.1,
 }}
 >
 {value}
 </span>
 <span
 style={{
 fontSize: 11,
 fontWeight: 600,
 color: BRAND.textTertiary,
 textTransform: "uppercase",
 letterSpacing: "0.06em",
 textAlign: "center",
 }}
 >
 {label}
 </span>
 </div>
 );
}

// ─── Stat Row ────────────────────────────────────────────────────────────────
function StatRow({
 label,
 value,
 color,
}: {
 label: string;
 value: number | string;
 color?: string;
}) {
 return (
 <div
 style={{
 display: "flex",
 justifyContent: "space-between",
 alignItems: "center",
 padding: "8px 0",
 borderBottom: `1px solid ${BRAND.borderLight}`,
 }}
 >
 <span style={{ fontSize: 13, color: BRAND.textSecondary }}>{label}</span>
 <span
 style={{
 fontSize: 14,
 fontWeight: 700,
 color: color || BRAND.textPrimary,
 minWidth: 28,
 textAlign: "right",
 }}
 >
 {value}
 </span>
 </div>
 );
}

// ─── Severity Badge ──────────────────────────────────────────────────────────
function SeverityBadge({ severity }: { severity: string }) {
 const bg = severityColor(severity);
 return (
 <span
 style={{
 display: "inline-block",
 padding: "2px 10px",
 borderRadius: 12,
 fontSize: 11,
 fontWeight: 700,
 color: BRAND.white,
 background: bg,
 textTransform: "capitalize",
 letterSpacing: "0.02em",
 }}
 >
 {severity}
 </span>
 );
}

function StatusBadge({ status }: { status: string }) {
 const isOpen = status.toLowerCase() === "open";
 return (
 <span
 style={{
 display: "inline-block",
 padding: "2px 10px",
 borderRadius: 12,
 fontSize: 11,
 fontWeight: 600,
 color: isOpen ? BRAND.severityHigh : BRAND.severityLow,
 background: isOpen ? "rgba(234,88,12,0.1)" : "rgba(22,163,74,0.1)",
 textTransform: "capitalize",
 }}
 >
 {status}
 </span>
 );
}

// ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
// SIDEBAR
