function Sidebar({
 activeSection,
 onNavigate,
}: {
 activeSection: SectionKey;
 onNavigate: (key: SectionKey) => void;
}) {
 const [hovered, setHovered] = useState<SectionKey | null>(null);

 return (
 <aside
 style={{
 width: 220,
 minWidth: 220,
 height: "100vh",
 background: BRAND.white,
 borderRight: `1px solid ${BRAND.border}`,
 display: "flex",
 flexDirection: "column",
 overflowY: "auto",
 flexShrink: 0,
 }}
 >
 {/* Brand Header */}
 <div
 style={{
 padding: "22px 18px 18px",
 borderBottom: `1px solid ${BRAND.border}`,
 }}
 >
 <div
 style={{
 fontSize: 15,
 fontWeight: 700,
 color: BRAND.navy,
 letterSpacing: "0.01em",
 lineHeight: 1.3,
 }}
 >
 Industrial Supply Co.
 </div>
 <div
 style={{
 fontSize: 10.5,
 fontWeight: 600,
 color: BRAND.textTertiary,
 textTransform: "uppercase",
 letterSpacing: "0.08em",
 marginTop: 4,
 }}
 >
 Operations Admin
 </div>
 </div>

 {/* Nav Items */}
 <nav style={{ flex: 1, padding: "6px 0" }}>
 {NAV_ITEMS.map((item) => {
 const isActive = item.key === activeSection;
 const isHover = item.key === hovered && !isActive;

 let bg = "transparent";
 let textColor = BRAND.textPrimary;
 let fontWeight: number | string = 400;

 if (isActive) {
 bg = BRAND.navy;
 textColor = BRAND.white;
 fontWeight = 600;
 } else if (isHover) {
 bg = "#f1f5f9";
 }

 return (
 <button
 key={item.key}
 onClick={() => onNavigate(item.key)}
 onMouseEnter={() => setHovered(item.key)}
 onMouseLeave={() => setHovered(null)}
 style={{
 display: "flex",
 alignItems: "center",
 gap: 12,
 width: "100%",
 padding: "10px 18px",
 border: "none",
 background: bg,
 color: textColor,
 fontSize: 13.5,
 fontWeight,
 fontFamily: "inherit",
 cursor: "pointer",
 textAlign: "left",
 transition: "background 0.12s ease",
 borderLeft: isActive ? `3px solid ${BRAND.accent}` : "3px solid transparent",
 }}
 >
 <span
 style={{
 width: 20,
 textAlign: "center",
 fontSize: 14,
 flexShrink: 0,
 opacity: isActive ? 1 : 0.7,
 }}
 >
 {item.icon}
 </span>
 {item.label}
 </button>
 );
 })}
 </nav>

 {/* Footer */}
 <div
 style={{
 padding: "14px 18px",
 borderTop: `1px solid ${BRAND.border}`,
 fontSize: 10,
 color: BRAND.textTertiary,
 textAlign: "center",
 letterSpacing: "0.02em",
 }}
 >
 Industrial Ops v2.0
 </div>
 </aside>
 );
}

// ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
// DASHBOARD LANDING
// ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
function DashboardLanding({ onNavigate }: { onNavigate: (key: SectionKey) => void }) {
 const [kpis, setKpis] = useState<KpiData | null>(null);
 const [operator, setOperator] = useState<OperatorData | null>(null);
 const [loading, setLoading] = useState(true);
 const [error, setError] = useState(false);

 useEffect(() => {
 let mounted = true;
 Promise.all([
 apiFetch<KpiData>(KPIS_API),
 apiFetch<OperatorData>(OPERATOR_API),
 ]).then(([k, o]) => {
 if (!mounted) return;
 if (!k && !o) setError(true);
 setKpis(k);
 setOperator(o);
 setLoading(false);
 });
 return () => { mounted = false; };
 }, []);

 if (loading) return <LoadingState message="Loading dashboard data…" />;

 // Fallback values
 const activeOrders = operator?.activeOrders ?? 0;
 const totalStock = kpis?.totalStock ?? 0;
