 const availableResources = operator?.availableResources ?? 0;
 const inProgress = operator?.inProgressOrders ?? 0;
 const planned = operator?.plannedOrders ?? 0;
 const maintenance = operator?.maintenanceRequired ?? 0;
 const pendingRequests = operator?.pendingRequests ?? 0;
