 display: "grid",
 gridTemplateColumns: "1fr 1fr",
 gap: 16,
 marginBottom: 20,
 };

 const threeCol: CSSProperties = {
 display: "grid",
 gridTemplateColumns: "1fr 1fr 1fr",
 gap: 16,
 marginBottom: 20,
 };

 return (
 <div style={{ padding: "28px 32px", maxWidth: 1400, margin: "0 auto" }}>
 {/* Page Header */}
 <div style={{ marginBottom: 24 }}>
 <h1 style={{ margin: 0, fontSize: 24, fontWeight: 700, color: BRAND.navy }}>
 Industrial Operations Dashboard
 </h1>
 <p style={{ margin: "6px 0 0", fontSize: 14, color: BRAND.textSecondary }}>
 Real-time overview of production, inventory, alerts, and operational metrics
 </p>
 </div>

 {error && (
 <div
 style={{
 background: "rgba(220,38,38,0.06)",
 border: `1px solid rgba(220,38,38,0.2)`,
 borderRadius: 8,
 padding: "12px 16px",
 marginBottom: 20,
 fontSize: 13,
 color: BRAND.severityCritical,
 }}
 >
 ⚠ Unable to fetch some dashboard data. Displaying available information.
 </div>
 )}

 {/* KPI Cards Row */}
 <div style={gridRow}>
 <KpiCard value={activeOrders} label="Active Production Orders" color={BRAND.navy} />
 <KpiCard value={totalStock} label="Inventory Stock Items" color={BRAND.info} />
 <KpiCard value={openAlerts} label="Active Alerts" color={openAlerts > 0 ? BRAND.severityHigh : BRAND.severityLow} />
 <KpiCard value={availableResources} label="Available Resources" color={BRAND.severityLow} />
 </div>

 {/* Production & Customer Orders Row */}
 <div style={twoCol}>
 {/* Production Overview */}
 <Card>
 <CardTitle>Production Overview</CardTitle>
 <StatRow label="In-Progress Orders" value={inProgress} color={BRAND.info} />
 <StatRow label="Planned Orders" value={planned} />
 <StatRow label="Maintenance Required" value={maintenance} color={maintenance > 0 ? BRAND.severityHigh : BRAND.textPrimary} />
 <div style={{ marginTop: 14 }}>
 <button
 onClick={() => onNavigate("production")}
 style={{
 background: "none",
 border: "none",
 color: BRAND.accent,
 fontSize: 12.5,
 fontWeight: 600,
 cursor: "pointer",
 padding: 0,
 fontFamily: "inherit",
 }}
 >
 View Production Details →
 </button>
 </div>
 </Card>

 {/* Customer Orders */}
 <Card>
 <CardTitle>Customer Orders</CardTitle>
 <StatRow label="Pending Requests" value={pendingRequests} color={pendingRequests > 0 ? BRAND.severityHigh : BRAND.textPrimary} />
 <StatRow label="Pending Approval" value={requests?.pendingApproval ?? 0} />
 <StatRow label="In Progress" value={requests?.inProgress ?? 0} color={BRAND.info} />
 <StatRow label="Completed" value={requests?.completed ?? 0} color={BRAND.severityLow} />
 <div style={{ marginTop: 14 }}>
 <button
 onClick={() => onNavigate("customer-orders")}
 style={{
 background: "none",
 border: "none",
 color: BRAND.accent,
 fontSize: 12.5,
 fontWeight: 600,
 cursor: "pointer",
 padding: 0,
 fontFamily: "inherit",
 }}
 >
 View All Orders →
 </button>
 </div>
 </Card>
 </div>

 {/* Inventory Overview - Full Width */}
 <Card style={{ marginBottom: 20 }}>
 <CardTitle>Inventory Overview</CardTitle>
 {categories.length > 0 ? (
 <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(200px, 1fr))", gap: 12 }}>
 {categories.map((cat) => (
 <div
 key={cat.type}
 style={{
 padding: "14px 16px",
 borderRadius: 8,
 border: `1px solid ${BRAND.border}`,
 background: "#f8fafc",
 }}
 >
 <div style={{ fontSize: 12, color: BRAND.textSecondary, marginBottom: 6 }}>
 {cat.label}
 </div>
 <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline" }}>
 <span style={{ fontSize: 20, fontWeight: 700, color: BRAND.navy }}>
 {cat.count}
 </span>
 <span style={{ fontSize: 11, color: BRAND.textTertiary }}>
 {cat.availableQty.toLocaleString()} units
 </span>
 </div>
 </div>
 ))}
 </div>
 ) : (
 <div style={{ fontSize: 13, color: BRAND.textTertiary, padding: "12px 0" }}>
 No category data available
 </div>
 )}
 <div style={{ marginTop: 14 }}>
 <button
 onClick={() => onNavigate("inventory")}
 style={{
 background: "none",
 border: "none",
 color: BRAND.accent,
 fontSize: 12.5,
 fontWeight: 600,
 cursor: "pointer",
 padding: 0,
 fontFamily: "inherit",
 }}
