 <div style={{ fontSize: 22, fontWeight: 700, color: alertCritical > 0 ? BRAND.severityCritical : BRAND.textTertiary }}>
 {alertCritical}
 </div>
 <div style={{ fontSize: 10, fontWeight: 600, color: BRAND.textTertiary, textTransform: "uppercase", letterSpacing: "0.05em" }}>
 Critical
 </div>
 </div>
 <div style={{ textAlign: "center", padding: "10px 0", borderRadius: 8, background: alertHigh > 0 ? "rgba(234,88,12,0.06)" : "#f8fafc" }}>
 <div style={{ fontSize: 22, fontWeight: 700, color: alertHigh > 0 ? BRAND.severityHigh : BRAND.textTertiary }}>
 {alertHigh}
 </div>
 <div style={{ fontSize: 10, fontWeight: 600, color: BRAND.textTertiary, textTransform: "uppercase", letterSpacing: "0.05em" }}>
 High
 </div>
 </div>
 <div style={{ textAlign: "center", padding: "10px 0", borderRadius: 8, background: "#f8fafc" }}>
