 fontWeight: 600,
 cursor: "pointer",
 padding: 0,
 fontFamily: "inherit",
 }}
 >
 Procurement →
 </button>
 <button
 onClick={() => onNavigate("suppliers")}
 style={{
 background: "none",
 border: "none",
 color: BRAND.accent,
 fontSize: 12.5,
 fontWeight: 600,
 cursor: "pointer",
 padding: 0,
 fontFamily: "inherit",
 }}
 >
 Suppliers →
 </button>
 </div>
 </Card>
 </div>

 {/* Demand Forecasting + Digital Twin Row */}
 <div style={twoCol}>
 <Card>
 <CardTitle>Demand Forecasting</CardTitle>
 <div style={{ display: "flex", flexDirection: "column", alignItems: "center", padding: "20px 0", gap: 8 }}>
 <span style={{ fontSize: 32, opacity: 0.3 }}>▲</span>
 <span style={{ fontSize: 13, color: BRAND.textTertiary }}>
 Predictive analytics and demand trend analysis
 </span>
 </div>
 <button
 onClick={() => onNavigate("forecasting")}
 style={{
 background: "none",
 border: "none",
 color: BRAND.accent,
 fontSize: 12.5,
 fontWeight: 600,
 cursor: "pointer",
 padding: 0,
 fontFamily: "inherit",
 }}
 >
 View Forecasting →
 </button>
 </Card>

 <Card>
 <CardTitle>Digital Twin</CardTitle>
 <div style={{ display: "flex", flexDirection: "column", alignItems: "center", padding: "20px 0", gap: 8 }}>
 <span style={{ fontSize: 32, opacity: 0.3 }}>◎</span>
 <span style={{ fontSize: 13, color: BRAND.textTertiary }}>
 Real-time simulation of industrial operations
 </span>
 </div>
 <button
 onClick={() => onNavigate("digital-twin")}
 style={{
 background: "none",
 border: "none",
 color: BRAND.accent,
 fontSize: 12.5,
 fontWeight: 600,
 cursor: "pointer",
 padding: 0,
 fontFamily: "inherit",
 }}
 >
 View Digital Twin →
 </button>
 </Card>
 </div>
 </div>
 );
}

// ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
// ALERTS SECTION
// ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
function AlertsSection() {
 const [data, setData] = useState<AlertsData | null>(null);
 const [loading, setLoading] = useState(true);
 const [error, setError] = useState(false);

 useEffect(() => {
 let mounted = true;
 apiFetch<AlertsData>(ALERTS_API).then((result) => {
 if (!mounted) return;
 if (!result) setError(true);
 setData(result);
 setLoading(false);
 });
 return () => { mounted = false; };
 }, []);

 if (loading) return <LoadingState message="Loading alerts…" />;

 const summary = data?.summary ?? { critical: 0, high: 0, medium: 0, low: 0, open: 0 };
 const alerts = data?.alerts ?? [];

 const severityCards: { key: string; label: string; color: string }[] = [
 { key: "critical", label: "Critical", color: BRAND.severityCritical },
 { key: "high", label: "High", color: BRAND.severityHigh },
 { key: "medium", label: "Medium", color: BRAND.severityMedium },
 { key: "low", label: "Low", color: BRAND.severityLow },
 ];

 const thStyle: CSSProperties = {
 padding: "10px 14px",
 fontSize: 11,
 fontWeight: 700,
 textTransform: "uppercase",
 letterSpacing: "0.05em",
 color: BRAND.textTertiary,
 textAlign: "left",
 borderBottom: `2px solid ${BRAND.border}`,
 background: "#f8fafc",
 };

 const tdStyle: CSSProperties = {
 padding: "12px 14px",
 fontSize: 13,
 color: BRAND.textPrimary,
 borderBottom: `1px solid ${BRAND.borderLight}`,
 verticalAlign: "middle",
 };

 return (
 <div style={{ padding: "28px 32px", maxWidth: 1400, margin: "0 auto" }}>
 {/* Header */}
 <div style={{ marginBottom: 24 }}>
 <h1 style={{ margin: 0, fontSize: 24, fontWeight: 700, color: BRAND.navy }}>
 Alerts & Exceptions
 </h1>
 <p style={{ margin: "6px 0 0", fontSize: 14, color: BRAND.textSecondary }}>
 Monitor and manage operational alerts across all systems
 </p>
 </div>

 {error && (
 <div
 style={{
 background: "rgba(220,38,38,0.06)",
 border: `1px solid rgba(220,38,38,0.2)`,
 borderRadius: 8,
 padding: "12px 16px",
 marginBottom: 20,
 fontSize: 13,
 color: BRAND.severityCritical,
 }}
 >
 ⚠ Unable to fetch alert data. Showing cached or partial results.
 </div>
 )}

 {/* Severity KPI Cards */}
 <div style={{ display: "grid", gridTemplateColumns: "repeat(4, 1fr)", gap: 16, marginBottom: 20 }}>
 {severityCards.map((card, idx) => (
 <div key={idx} style={{ minWidth: 0 }}>
 <KpiCard
 value={(summary as any)[card.key]}
 label={card.label}
 color={card.color}
 borderColor={card.color}
 />
 </div>
 ))}
 </div>

 {/* Critical Banner */}
 {summary.critical > 0 && (
 <div
 style={{
 padding: "14px 20px",
 borderRadius: 8,
 background: "rgba(220,38,38,0.06)",
 border: "1px solid rgba(220,38,38,0.15)",
 color: BRAND.severityCritical,
 fontSize: 13,
 fontWeight: 600,
 marginBottom: 20,
 display: "flex",
 alignItems: "center",
 gap: 8,
 }}
 >
 <span style={{ fontSize: 18 }}>⚠</span>
 {summary.critical} critical alert{summary.critical !== 1 ? "s" : ""} detected — immediate action recommended
 </div>
 )}

 {/* Alerts Table */}
 <Card style={{ padding: 0, overflow: "hidden" }}>
 <div style={{ padding: "18px 24px 14px", borderBottom: `1px solid ${BRAND.border}` }}>
 <h3 style={{ margin: 0, fontSize: 15, fontWeight: 700, color: BRAND.textPrimary }}>
 All Alerts
 </h3>
 <span style={{ fontSize: 12, color: BRAND.textTertiary }}>
 {alerts.length} alert{alerts.length !== 1 ? "s" : ""} • {summary.open} open
 </span>
 </div>

 {alerts.length === 0 ? (
 <div style={{ padding: 40, textAlign: "center", color: BRAND.textTertiary, fontSize: 14 }}>
 No alerts found. All systems are operating normally.
 </div>
 ) : (
 <div style={{ overflowX: "auto" }}>
 <table
 style={{
 width: "100%",
 borderCollapse: "collapse",
 minWidth: 700,
 }}
 >
 <thead>
 <tr>
 <th style={thStyle}>Number</th>
 <th style={thStyle}>Type</th>
 <th style={thStyle}>Severity</th>
 <th style={{ ...thStyle, minWidth: 200 }}>Message</th>
 <th style={thStyle}>Status</th>
 <th style={thStyle}>Date</th>
 </tr>
 </thead>
 <tbody>
 {alerts.map((alert) => (
 <tr key={alert.sys_id} style={{ transition: "background 0.1s" }}>
 <td style={{ ...tdStyle, fontWeight: 600, color: BRAND.info }}>
 {alert.number}
 </td>
 <td style={tdStyle}>{formatAlertType(alert.alert_type)}</td>
 <td style={tdStyle}>
 <SeverityBadge severity={alert.severity} />
 </td>
 <td style={{ ...tdStyle, color: BRAND.textSecondary, maxWidth: 320 }}>
 {alert.alert_message}
 </td>
 <td style={tdStyle}>
 <StatusBadge status={alert.status} />
 </td>
 <td style={{ ...tdStyle, fontSize: 12, color: BRAND.textTertiary, whiteSpace: "nowrap" }}>
 {formatDate(alert.alert_date)}
 </td>
 </tr>
 ))}
 </tbody>
 </table>
 </div>
 )}
 </Card>
 </div>
 );
}

// ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
// PLACEHOLDER SECTION
// ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
function PlaceholderSection({ title, description }: { title: string; description: string }) {
 return (
 <div style={{ padding: "28px 32px", maxWidth: 1400, margin: "0 auto" }}>
 <div style={{ marginBottom: 24 }}>
 <h1 style={{ margin: 0, fontSize: 24, fontWeight: 700, color: BRAND.navy }}>
 {title}
 </h1>
 <p style={{ margin: "6px 0 0", fontSize: 14, color: BRAND.textSecondary }}>
 {description}
 </p>
 </div>
 <Card
 style={{
 display: "flex",
 flexDirection: "column",
 alignItems: "center",
 justifyContent: "center",
 padding: "60px 32px",
 textAlign: "center",
 }}
 >
 <div
 style={{
 width: 64,
 height: 64,
 borderRadius: 16,
 background: "#f1f5f9",
 display: "flex",
 alignItems: "center",
 justifyContent: "center",
 marginBottom: 16,
 fontSize: 28,
 color: BRAND.textTertiary,
 }}
 >
 {NAV_ITEMS.find((n) => n.label === title)?.icon || "◆"}
 </div>
 <div style={{ fontSize: 16, fontWeight: 600, color: BRAND.textPrimary, marginBottom: 8 }}>
 {title}
 </div>
 <div style={{ fontSize: 13, color: BRAND.textTertiary, maxWidth: 400 }}>
 Section content — navigate from Dashboard overview cards for quick context, or use this section for detailed management.
 </div>
 </Card>
 </div>
 );
}

// ─── Placeholder section definitions ────────────────────────────────────────
const PLACEHOLDERS: Record<string, { title: string; description: string }> = {
 "customer-orders": {
 title: "Customer Orders",
 description: "Track and manage customer orders, fulfillment status, and delivery timelines.",
 },
 production: {
 title: "Production & Machines",
 description: "Monitor production lines, machine status, and manufacturing output.",
 },
 schedule: {
 title: "Schedule Planner",
 description: "Plan and manage production schedules, shifts, and resource allocation.",
 },
 inventory: {
 title: "Inventory",
 description: "View current stock levels, warehouse locations, and inventory movements.",
 },
 procurement: {
 title: "Procurement",
 description: "Manage purchase orders, vendor quotes, and procurement workflows.",
 },
 suppliers: {
 title: "Suppliers",
 description: "Manage supplier relationships, performance metrics, and contact information.",
 },
 forecasting: {
 title: "Demand Forecasting",
 description: "Analyze demand trends, generate forecasts, and plan for future inventory needs.",
 },
 "digital-twin": {
 title: "Digital Twin",
 description: "Visualize and simulate your industrial operations with digital twin models.",
 },
};

// ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
// MAIN CONTENT ROUTER
// ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
function MainContent({
 activeSection,
 onNavigate,
}: {
 activeSection: SectionKey;
 onNavigate: (key: SectionKey) => void;
}) {
 if (activeSection === "dashboard") {
 return <DashboardLanding onNavigate={onNavigate} />;
 }
 if (activeSection === "alerts") {
 return <AlertsSection />;
 }
 const ph = PLACEHOLDERS[activeSection];
 if (ph) {
 return <PlaceholderSection title={ph.title} description={ph.description} />;
 }
 return <PlaceholderSection title="Unknown Section" description="" />;
}

// ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
// APP ROOT
// ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
function App() {
 const [activeSection, setActiveSection] = useState<SectionKey>("dashboard");

 const handleNavigate = (key: SectionKey) => {
 setActiveSection(key);
 window.location.hash = key;
 };

 // Check hash on mount for deep-linking
 useEffect(() => {
 const hash = window.location.hash.replace("#", "") as SectionKey;
 if (hash && NAV_ITEMS.some((n) => n.key === hash)) {
 setActiveSection(hash);
 }
 }, []);

 return (
 <div
 style={{
 display: "flex",
 height: "100vh",
 width: "100%",
 fontFamily: '"Source Sans Pro", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif',
 margin: 0,
 padding: 0,
 }}
 >
 <Sidebar activeSection={activeSection} onNavigate={handleNavigate} />
 <main
 style={{
 flex: 1,
 height: "100vh",
 overflowY: "auto",
 background: BRAND.bgPage,
 }}
 >
 <MainContent activeSection={activeSection} onNavigate={handleNavigate} />
 </main>
 </div>
 );
}

// ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
// MOUNT
// ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
const rootEl = document.getElementById("root");
if (rootEl) {
 ReactDOM.createRoot(rootEl).render(<App />);
}
